PRAGMA foreign_keys = ON;
CREATE TABLE category(id TEXT PRIMARY KEY,name TEXT NOT NULL,parent_id TEXT REFERENCES category(id),sort_order INTEGER NOT NULL DEFAULT 0, CHECK(parent_id IS NULL OR parent_id<>id));
CREATE TABLE content(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,locale TEXT NOT NULL DEFAULT 'en',title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',alt_text TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('draft','processing','ready_for_review','published','archived')),latest_version INTEGER NOT NULL DEFAULT 1,active_version INTEGER,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),published_at TEXT,sort_score INTEGER NOT NULL DEFAULT 0,difficulty TEXT CHECK(difficulty IN ('easy','detailed') OR difficulty IS NULL),example_only INTEGER NOT NULL DEFAULT 0,provenance_json TEXT NOT NULL);
CREATE INDEX content_published_date ON content(status,published_at DESC,id DESC);
CREATE INDEX content_published_score ON content(status,sort_score DESC,id DESC);
CREATE INDEX content_published_title ON content(status,title COLLATE NOCASE,id);
CREATE INDEX content_difficulty ON content(status,difficulty,published_at DESC,id DESC);
CREATE TABLE content_revision(content_id TEXT NOT NULL REFERENCES content(id),version INTEGER NOT NULL,manifest_json TEXT NOT NULL,manifest_sha256 TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'ready_for_review',created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(content_id,version));
CREATE TABLE content_category(content_id TEXT NOT NULL REFERENCES content(id),category_id TEXT NOT NULL REFERENCES category(id),PRIMARY KEY(content_id,category_id));
CREATE INDEX category_content ON content_category(category_id,content_id);
CREATE TABLE content_tag(content_id TEXT NOT NULL REFERENCES content(id),tag TEXT NOT NULL,PRIMARY KEY(content_id,tag));
CREATE INDEX tag_content ON content_tag(tag,content_id);
CREATE TABLE content_age(content_id TEXT NOT NULL REFERENCES content(id),age TEXT NOT NULL CHECK(age IN ('kids','teens','adults')),PRIMARY KEY(content_id,age));
CREATE INDEX age_content ON content_age(age,content_id);
CREATE TABLE asset(asset_id TEXT PRIMARY KEY,content_id TEXT NOT NULL REFERENCES content(id),content_version INTEGER NOT NULL,role TEXT NOT NULL,object_key TEXT NOT NULL,original_key TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL CHECK(bytes>0),sha256 TEXT NOT NULL,width INTEGER,height INTEGER,page_count INTEGER,asset_version INTEGER NOT NULL,verified INTEGER NOT NULL DEFAULT 0,UNIQUE(content_id,content_version,role));
CREATE INDEX asset_content ON asset(content_id,content_version,role);
CREATE TABLE asset_review(sha256 TEXT NOT NULL,role TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL,width INTEGER,height INTEGER,page_count INTEGER,bw INTEGER NOT NULL,review_version INTEGER NOT NULL DEFAULT 1,reviewed_at TEXT NOT NULL,PRIMARY KEY(sha256,role));
CREATE TABLE slug_redirect(old_slug TEXT PRIMARY KEY,content_id TEXT NOT NULL REFERENCES content(id),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE import_job(id TEXT PRIMARY KEY,idempotency_key TEXT NOT NULL UNIQUE,payload_sha256 TEXT NOT NULL,status TEXT NOT NULL,owner TEXT NOT NULL,total INTEGER NOT NULL DEFAULT 1,error_code TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE import_item(import_id TEXT NOT NULL REFERENCES import_job(id),content_id TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL,error_code TEXT,PRIMARY KEY(import_id,content_id));
CREATE TABLE outbox_event(seq INTEGER PRIMARY KEY AUTOINCREMENT,event_id TEXT NOT NULL UNIQUE,content_id TEXT NOT NULL,version INTEGER NOT NULL,event_type TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),delivered_at TEXT,processed_at TEXT,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT);
CREATE INDEX outbox_pending ON outbox_event(processed_at,seq);
CREATE TABLE processed_event(event_id TEXT PRIMARY KEY,processed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE audit_event(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,target_id TEXT NOT NULL,version INTEGER,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TRIGGER content_event AFTER UPDATE OF active_version,status ON content WHEN NEW.active_version IS NOT NULL AND (NEW.active_version IS NOT OLD.active_version OR NEW.status<>OLD.status) BEGIN
 INSERT INTO outbox_event(event_id,content_id,version,event_type) VALUES(lower(hex(randomblob(16))),NEW.id,NEW.latest_version,CASE WHEN NEW.status='published' THEN 'published' ELSE 'archived' END);
END;
CREATE TRIGGER content_redirect AFTER UPDATE OF slug ON content WHEN OLD.slug<>NEW.slug BEGIN INSERT INTO slug_redirect(old_slug,content_id) VALUES(OLD.slug,NEW.id) ON CONFLICT(old_slug) DO UPDATE SET content_id=excluded.content_id; END;
CREATE TABLE category_count(category_id TEXT PRIMARY KEY REFERENCES category(id),published_count INTEGER NOT NULL DEFAULT 0);
CREATE TRIGGER count_publish AFTER UPDATE OF status ON content WHEN NEW.status='published' AND OLD.status<>'published' BEGIN INSERT INTO category_count(category_id,published_count) SELECT category_id,1 FROM content_category WHERE content_id=NEW.id ON CONFLICT(category_id) DO UPDATE SET published_count=published_count+1; END;
CREATE TRIGGER count_archive AFTER UPDATE OF status ON content WHEN OLD.status='published' AND NEW.status<>'published' BEGIN UPDATE category_count SET published_count=MAX(0,published_count-1) WHERE category_id IN (SELECT category_id FROM content_category WHERE content_id=NEW.id); END;
CREATE TABLE creator_job(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,payload_sha256 TEXT NOT NULL,parameters_json TEXT NOT NULL,source_revision TEXT NOT NULL,input_key TEXT,model TEXT NOT NULL,status TEXT NOT NULL,reservation_micros INTEGER NOT NULL,daily_limit_micros INTEGER NOT NULL,monthly_limit_micros INTEGER NOT NULL,concurrent_limit INTEGER NOT NULL,session_limit INTEGER NOT NULL,error_code TEXT,line_art_key TEXT,color_preview_key TEXT,pdf_key TEXT,width INTEGER,height INTEGER,actual_cost_micros INTEGER,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,started_at TEXT,completed_at TEXT,UNIQUE(owner_id,idempotency_key));
CREATE INDEX creator_owner ON creator_job(owner_id,created_at DESC);
CREATE INDEX creator_budget ON creator_job(created_at,status);
CREATE TRIGGER creator_budget BEFORE INSERT ON creator_job BEGIN
 SELECT CASE WHEN (SELECT COALESCE(SUM(reservation_micros),0) FROM creator_job WHERE substr(created_at,1,10)=substr(NEW.created_at,1,10) AND status NOT IN ('cancelled','rejected'))+NEW.reservation_micros>NEW.daily_limit_micros THEN RAISE(ABORT,'DAILY_BUDGET_EXCEEDED') END;
 SELECT CASE WHEN (SELECT COALESCE(SUM(reservation_micros),0) FROM creator_job WHERE substr(created_at,1,7)=substr(NEW.created_at,1,7) AND status NOT IN ('cancelled','rejected'))+NEW.reservation_micros>NEW.monthly_limit_micros THEN RAISE(ABORT,'MONTHLY_BUDGET_EXCEEDED') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM creator_job WHERE status IN ('queued','running','processing'))>=NEW.concurrent_limit THEN RAISE(ABORT,'CONCURRENCY_LIMIT') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM creator_job WHERE owner_id=NEW.owner_id AND substr(created_at,1,10)=substr(NEW.created_at,1,10) AND status NOT IN ('cancelled','rejected'))>=NEW.session_limit THEN RAISE(ABORT,'SESSION_LIMIT') END;
END;
CREATE TABLE creator_upload(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,object_key TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,status TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE capacity_snapshot(database_role TEXT PRIMARY KEY,bytes INTEGER NOT NULL,measured_at TEXT NOT NULL,limit_bytes INTEGER NOT NULL DEFAULT 10000000000);
