INSERT INTO category(id,name,parent_id,sort_order) VALUES ('woodland','Woodland','animals',1),('pets','Pets','animals',2),('farm-animals','Farm animals','animals',3),('ocean-life','Ocean life','animals',4),('birds','Birds','animals',5);
CREATE TRIGGER count_category_add AFTER INSERT ON content_category WHEN EXISTS(SELECT 1 FROM content WHERE id=NEW.content_id AND status='published') BEGIN INSERT INTO category_count(category_id,published_count) VALUES(NEW.category_id,1) ON CONFLICT(category_id) DO UPDATE SET published_count=published_count+1; END;
CREATE TRIGGER count_category_delete AFTER DELETE ON content_category WHEN EXISTS(SELECT 1 FROM content WHERE id=OLD.content_id AND status='published') BEGIN UPDATE category_count SET published_count=MAX(0,published_count-1) WHERE category_id=OLD.category_id; END;
